#include "sio_private.h"

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

SInt16 sio_tx_text (Sio sio , HVA_Const_Char_P text)
{
  return sio_tx_text_t (sio , text , 0) ;
}

//--------------------------------------------------------------------------//

SInt16 sio_tx_text_t (Sio sio , HVA_Const_Char_P text , Sio_Timeout timeout)
{
  SInt16 sio_status = SIO_OK ;

  while (*text)
    {
      sio_status = sio_tx_t (sio , *text++ , timeout) ;

      if (sio_status != SIO_OK)
        {
          break ;
        }
    }

  return sio_status ;
}

